// A direct Rust implementation of the described behavior.
// - `starts_with` is given as a spec-style definition (here: a normal function over slices).
// - `has_prefix` checks whether a single Vec<char> starts with a prefix Vec<char>.
// - `filter_by_prefix` keeps exactly those sequences that start with the prefix, preserving order.

pub fn starts_with(s: &[char], p: &[char]) -> bool {
    // Empty prefix matches everything.
    if p.is_empty() {
        return true;
    }
    // If s is shorter than p, it cannot start with p.
    if s.len() < p.len() {
        return false;
    }
    // All characters must match up to p.len().
    for i in 0..p.len() {
        if s[i] != p[i] {
            return false;
        }
    }
    true
}

pub fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v.as_slice(), p.as_slice())
}

pub fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    for s in xs {
        if has_prefix(&s, &p) {
            filtered.push(s); // preserves relative order
        }
    }
    filtered
}

